import { createFileRoute, Link, useNavigate } from "@tanstack/react-router";
import { useQuery } from "@tanstack/react-query";
import { useServerFn } from "@tanstack/react-start";
import { useState } from "react";
import { Camera, FileText, Loader2, Upload } from "lucide-react";
import { toast } from "sonner";
import { supabase } from "@/integrations/supabase/client";
import { generatePatternDraft } from "@/lib/pattern.functions";
import { AppShell } from "@/components/AppShell";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";

export const Route = createFileRoute("/_authenticated/pattern/")({
  head: () => ({
      meta: [
            { title: "Pattern draft from a photo — Stitchology" },
                  { name: "description", content: "Take a photo of a garment or bag and get a starter sewing pattern draft and project guide." },
                        { property: "og:title", content: "Photo to pattern draft — Stitchology" },
                              { property: "og:description", content: "Turn a photo into a starter sewing pattern draft." },
                                  ],
                                    }),
                                      component: PatternPage,
                                      });

                                      // Resizes and compresses images safely across iOS Safari, Android, and Desktop
                                      async function resize(file: File): Promise<string> {
                                        // Method 1: Try modern createImageBitmap
                                          if (typeof createImageBitmap !== "undefined") {
                                              try {
                                                    const img = await createImageBitmap(file);
                                                          const scale = Math.min(1, 1024 / Math.max(img.width, img.height));
                                                                const c = document.createElement("canvas");
                                                                      c.width = Math.max(1, Math.round(img.width * scale));
                                                                            c.height = Math.max(1, Math.round(img.height * scale));
                                                                                  const ctx = c.getContext("2d");
                                                                                        if (ctx) {
                                                                                                ctx.drawImage(img, 0, 0, c.width, c.height);
                                                                                                        return c.toDataURL("image/jpeg", 0.85);
                                                                                                              }
                                                                                                                  } catch {
                                                                                                                        // Fall through to FileReader on mobile Safari/HEIC decode failure
                                                                                                                            }
                                                                                                                              }

                                                                                                                                // Method 2: Standard HTML Image + FileReader fallback for mobile
                                                                                                                                  return new Promise((resolve, reject) => {
                                                                                                                                      const reader = new FileReader();
                                                                                                                                          reader.onerror = () => reject(new Error("Failed to read image file"));
                                                                                                                                              reader.onload = (e) => {
                                                                                                                                                    const src = e.target?.result as string;
                                                                                                                                                          const img = new Image();
                                                                                                                                                                img.onerror = () => reject(new Error("Failed to decode image"));
                                                                                                                                                                      img.onload = () => {
                                                                                                                                                                              const scale = Math.min(1, 1024 / Math.max(img.width, img.height));
                                                                                                                                                                                      const c = document.createElement("canvas");
                                                                                                                                                                                              c.width = Math.max(1, Math.round(img.width * scale));
                                                                                                                                                                                                      c.height = Math.max(1, Math.round(img.height * scale));
                                                                                                                                                                                                              const ctx = c.getContext("2d");
                                                                                                                                                                                                                      if (!ctx) {
                                                                                                                                                                                                                                reject(new Error("Canvas context unavailable"));
                                                                                                                                                                                                                                          return;
                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                          ctx.drawImage(img, 0, 0, c.width, c.height);
                                                                                                                                                                                                                                                                  resolve(c.toDataURL("image/jpeg", 0.85));
                                                                                                                                                                                                                                                                        };
                                                                                                                                                                                                                                                                              img.src = src;
                                                                                                                                                                                                                                                                                  };
                                                                                                                                                                                                                                                                                      reader.readAsDataURL(file);
                                                                                                                                                                                                                                                                                        });
                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                        function PatternPage() {
                                                                                                                                                                                                                                                                                          const navigate = useNavigate();
                                                                                                                                                                                                                                                                                            const generate = useServerFn(generatePatternDraft);
                                                                                                                                                                                                                                                                                              const [image, setImage] = useState<string | null>(null);
                                                                                                                                                                                                                                                                                                const [notes, setNotes] = useState("");
                                                                                                                                                                                                                                                                                                  const [busy, setBusy] = useState(false);

                                                                                                                                                                                                                                                                                                    const { data: drafts = [] } = useQuery({
                                                                                                                                                                                                                                                                                                        queryKey: ["drafts"],
                                                                                                                                                                                                                                                                                                            queryFn: async () => {
                                                                                                                                                                                                                                                                                                                  const { data, error } = await supabase
                                                                                                                                                                                                                                                                                                                          .from("pattern_drafts")
                                                                                                                                                                                                                                                                                                                                  .select("id,title,created_at")
                                                                                                                                                                                                                                                                                                                                          .order("created_at", { ascending: false });
                                                                                                                                                                                                                                                                                                                                                if (error) throw error;
                                                                                                                                                                                                                                                                                                                                                      return data;
                                                                                                                                                                                                                                                                                                                                                          },
                                                                                                                                                                                                                                                                                                                                                            });

                                                                                                                                                                                                                                                                                                                                                              async function onFile(f?: File) {
                                                                                                                                                                                                                                                                                                                                                                  if (!f) return;
                                                                                                                                                                                                                                                                                                                                                                      try {
                                                                                                                                                                                                                                                                                                                                                                            const scaled = await resize(f);
                                                                                                                                                                                                                                                                                                                                                                                  setImage(scaled);
                                                                                                                                                                                                                                                                                                                                                                                      } catch {
                                                                                                                                                                                                                                                                                                                                                                                            toast.error("Couldn't read that image. Please try another photo.");
                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                    async function go() {
                                                                                                                                                                                                                                                                                                                                                                                                        if (!image) return;
                                                                                                                                                                                                                                                                                                                                                                                                            setBusy(true);
                                                                                                                                                                                                                                                                                                                                                                                                                try {
                                                                                                                                                                                                                                                                                                                                                                                                                      const { id } = await generate({ data: { image, notes: notes || undefined } });
                                                                                                                                                                                                                                                                                                                                                                                                                            navigate({ to: "/pattern/$id", params: { id } });
                                                                                                                                                                                                                                                                                                                                                                                                                                } catch (e) {
                                                                                                                                                                                                                                                                                                                                                                                                                                      toast.error(e instanceof Error ? e.message : "Something went wrong");
                                                                                                                                                                                                                                                                                                                                                                                                                                            setBusy(false);
                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                                                    return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                        <AppShell>
                                                                                                                                                                                                                                                                                                                                                                                                                                                              <div className="mx-auto max-w-2xl px-4 py-6">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <h1 className="text-3xl font-semibold">Pattern from a photo</h1>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <p className="mt-1 text-muted-foreground">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        Snap a garment, bag or idea you love. We'll draft a starter pattern and project guide.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </p>


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              {image ? (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div className="mt-5">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <img
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  src={image}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                alt="Your photo"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              className="max-h-96 w-full rounded-2xl object-contain bg-muted"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <button
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    onClick={() => setImage(null)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  className="mt-2 text-sm text-muted-foreground underline"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                disabled={busy}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          Choose a different photo
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ) : (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <div className="stitch mt-5 grid gap-3 rounded-3xl p-5">
{/* The real file input sits directly on top of each button: zero JS delegation,
    so tablets always fire the OS picker. No `capture` — the OS shows its own
    action sheet (Take Photo / Photo Library / Choose File). */}
<div className="relative">
  <div className="inline-flex h-14 w-full cursor-pointer items-center justify-center gap-2 rounded-full bg-primary px-8 text-base font-medium text-primary-foreground shadow-sm">
    <Camera className="size-5" /> Take a photo
  </div>
  <input
    type="file"
    accept="image/*"
    aria-label="Take a photo"
    className="absolute inset-0 h-full w-full cursor-pointer opacity-0"
    onChange={(e) => {
      onFile(e.target.files?.[0]);
      e.target.value = "";
    }}
  />
</div>
<div className="relative">
  <div className="inline-flex h-14 w-full cursor-pointer items-center justify-center gap-2 rounded-full border border-input bg-background px-8 text-base font-medium text-foreground shadow-sm">
    <Upload className="size-5" /> Upload from gallery
  </div>
  <input
    type="file"
    accept="image/*"
    aria-label="Upload from gallery"
    className="absolute inset-0 h-full w-full cursor-pointer opacity-0"
    onChange={(e) => {
      onFile(e.target.files?.[0]);
      e.target.value = "";
    }}
  />
</div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            )}

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <label className="mt-5 block text-sm font-semibold" htmlFor="notes">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              Notes (optional)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </label>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <Textarea
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        id="notes"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  value={notes}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            onChange={(e) => setNotes(e.target.value)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      placeholder="e.g. size M, want it in linen, make it shorter"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                className="mt-1.5"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        />

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <Button
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          size="lg"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    className="mt-5 h-14 w-full rounded-full text-base"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              disabled={!image || busy}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        onClick={go}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          {busy ? (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <Loader2 className="size-5 animate-spin" /> Drafting your pattern… (up to a minute)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ) : (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      "Create pattern draft"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </Button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <p className="mt-3 text-xs text-muted-foreground">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          Drafts are a creative starting point. Always check measurements and make a test version before cutting your fabric.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </p>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          {drafts.length > 0 && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <h2 className="mt-10 text-lg font-semibold">Your drafts</h2>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <ul className="mt-2 space-y-2">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          {drafts.map((d) => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <li key={d.id}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <Link
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                to="/pattern/$id"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    params={{ id: d.id }}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        className="flex items-center gap-3 rounded-xl border bg-card p-3"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <FileText className="size-4 text-primary" />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <span className="line-clamp-1 flex-1 font-medium">{d.title}</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <span className="text-xs text-muted-foreground">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            {new Date(d.created_at).toLocaleDateString()}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </Link>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </li>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ))}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </ul>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </AppShell>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          